class GenericError extends Error {
  constructor(message: string) {
    super(message); // 'message' is a property of Error
    this.name = 'GenericError';
    // Maintains proper stack trace for where our error was thrown (only available on V8)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, GenericError);
    }
  }
}

class SessionExpiredError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SessionExpiredError';
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, SessionExpiredError);
    }
  }
}

async function fetchData(url: string): Promise<any> {
  try {
    const response = await fetch(url);

    // Check for session expiry
    if (response.status === 401) { // 401 is typically used for authentication errors
      throw new SessionExpiredError('Session has expired. Please log in again.');
    }

    // Handle other potential bad statuses
    if (!response.ok) {
      throw new GenericError('An error occurred while fetching data.');
    }

    const data = await response.json();
    return data;
  } catch (error) {
    // Re-throw the error to be handled by the caller
    throw error;
  }
}

async function handleDataRequest(url: string) {
  try {
    const data = await fetchData(url);
    console.log('Data fetched successfully:', data);
  } catch (error) {
    if (error instanceof SessionExpiredError) {
      console.error('Session expired:', error.message);
      // Handle session expiry, for example, redirect to login
    } else if (error instanceof GenericError) {
      console.error('A generic error occurred:', error.message);
      // Handle generic errors
    } else {
      console.error('An unexpected error occurred:', error);
      // Handle unexpected errors
    }
  }
}

// Usage example:
handleDataRequest('https://api.example.com/data');

